# team-fight v2: parent version 1 (tune-5). Adds team coordination:
# - Regroup: when outnumbered nearby (enemies_within(5) > allies_within(5) + ENEMY_MARGIN), step away
#   from the nearest enemy toward our side instead of trading alone.
# - Kiting: a ranged champion with a melee enemy adjacent and an ally nearby steps away first.
# - Focus fire: name the weakest visible enemy champion as the team target; every champion in reach
#   attacks it and casts damage/stun/aoe at it.
# - Rich camps: go for the closest goal intersected with rich_spawns(15) when it is only RICH_EXTRA
#   tiles farther than the nearest goal, or when allies already claim it (claim_count > 0).
# - Claims: claim the camp we walk to, so allies can commit to the same group.
# Farming, tributing, recall and draft rules are unchanged from version 1.

# ability-type-aware casting: shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep rich = rich_spawns(15)
keep RICH_EXTRA = 4
keep ENEMY_MARGIN = 1

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 2 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 30% health while in danger, recall once clear
if not at_spawn and health() < 0.3 * max_health():
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not in_danger():
    recall()
    end_turn()

# ---- team fight ----
# regroup: outnumbered nearby, so step away from the nearest enemy instead of trading alone
let outnumbered = enemies_within(5) > allies_within(5) + ENEMY_MARGIN
if outnumbered and not at_spawn:
    let foe = nearest(enemies_visible())
    if exists(foe):
        move_away_from( unit_position(foe) )
        end_turn()

# kite: a ranged champion with a melee enemy adjacent and an ally nearby steps away first
if i_am_ranged() and enemies_within(1) > 0 and allies_within(3) > 0:
    let adj = nearest(enemies_visible())
    if exists(adj):
        move_away_from( unit_position(adj) )
        end_turn()

# focus fire: name the weakest visible enemy champion (not on its spawn) as the team target
let wk = weakest(enemies_visible())
if exists(wk) and not contains( spawn_region(enemy()), unit_position(wk) ):
    set_team_target(wk)

# every champion that can reach the team target hits it and casts at it
let tt = team_target()
if exists(tt) and not contains( spawn_region(enemy()), unit_position(tt) ):
    if distance(unit_position(tt), position()) <= 1 or (i_am_ranged() and distance(unit_position(tt), position()) <= 3):
        cast_on(0, tt)
        cast_on(1, tt)
        attack(tt)
        end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 25 or round_number() > 1500 or health() < 0.3 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    end_turn()

# nothing tributed by round 300: go for monoliths too
if team_score(ally()) == 0 and round_number() > 300:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() )
# rich camp groups (15+ gems) among the goals
let rich_goals = minus( goals, minus( goals, rich ) )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)

# rich-camp preference: go for a rich group when it is only a little farther than the nearest goal,
# or when allies already claim it (commit together)
let rgoal = closest(rich_goals)
if exists(rgoal) and distance(position(), rgoal) > 0 and (claim_count(rgoal) > 0 or distance(position(), rgoal) <= distance(position(), goal) + RICH_EXTRA):
    claim(rgoal)
    move_towards(rgoal)
    end_turn()

# on a dead camp of a group that is not cleared yet, walk to the nearest living camp instead
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()

# dash toward a far camp goal only on a turn with fuel to spare
if exists(goal) and distance(position(), goal) > 2 and fuel_remaining() > 55000:
    dash_to(0, goal)
    dash_to(1, goal)
if exists(goal):
    claim(goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

